export default function Lab({onNewSession}:{onNewSession:()=>void}){
 const [tab,setTab]=useState('lab'),[reactions,setReactions]=useState<Reaction[]>(seeds),[selected,setSelected]=useState('zn-hcl'),[inputs,setInputs]=useState<Measure[]>(structuredClone(seeds[0].defaults!)),[settings,setSettings]=useState(settingsDefault),[result,setResult]=useState<any>(null),[progress,setProgress]=useState(0),[running,setRunning]=useState(false),[loading,setLoading]=useState(false),[showMath,setShowMath]=useState(false),[toast,setToast]=useState(''),[error,setError]=useState(''),[help,setHelp]=useState(false),[signed,setSigned]=useState(false),[catalogError,setCatalogError]=useState(false),[questions,setQuestions]=useState<Question[]>([]),[generated,setGenerated]=useState<Question[]>([]),[savedIds,setSavedIds]=useState<string[]>([]),[questionCount,setQuestionCount]=useState(3),[editor,setEditor]=useState<Reaction|null>(null),[qEditor,setQEditor]=useState<Question|null>(null),[history,setHistory]=useState<any[]>([]),[prediction,setPrediction]=useState(''),[teacherTab,setTeacherTab]=useState('reactions'),[manual,setManual]=useState(''),[grade,setGrade]=useState(''),[balanceOpen,setBalanceOpen]=useState(false);
 const[forecast,setForecast]=useState(emptyForecast),[submittedForecast,setSubmittedForecast]=useState(emptyForecast);
 const [mode,setMode]=useState('learn'),[balancedFor,setBalancedFor]=useState(''),[measured,setMeasured]=useState<boolean[]>([]),[instrument,setInstrument]=useState<number|null>(null),[allowAuto,setAllowAuto]=useState(false),[target,setTarget]=useState('mixed'),[printTeacher,setPrintTeacher]=useState(false),[challengeId,setChallengeId]=useState('metal'),[completed,setCompleted]=useState<Record<string,boolean>>({}),[challengeFeedback,setChallengeFeedback]=useState('');
 useEffect(()=>{try{setAllowAuto(localStorage.getItem('bancada-auto-help')==='true');setCompleted(JSON.parse(localStorage.getItem('bancada-discoveries')??'{}'));}catch{}},[]);
 const frame=useRef<number>(0),reaction=reactions.find(r=>r.id===selected)??reactions[0],done=progress===1;
 const loadCatalog=async()=>{try{const data=await api('/api/catalog');setReactions(data.reactions);setQuestions(data.questions);setSigned(data.signedIn);setCatalogError(false);}catch{setCatalogError(true);}};
 useEffect(()=>{loadCatalog();return()=>cancelAnimationFrame(frame.current);},[]);
 useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(''),4500);return()=>clearTimeout(t);},[toast]);
 const clear=()=>{setResult(null);setProgress(0);setError('');setManual('');setGrade('');};
 const newTrial=()=>onNewSession();
 const choose=(id:string)=>{if(running)return;const r=reactions.find(r=>r.id===id)!;setSelected(id);setInputs(structuredClone(r.defaults??r.reactants.map(defaultInput)));setPrediction('');setForecast(emptyForecast());setBalancedFor('');setMeasured([]);setChallengeFeedback('');clear();};
 const update=(i:number,key:string,value:any)=>{setMeasured(old=>old.map((v,j)=>j===i?false:v));setInputs(old=>old.map((x,j)=>i===j?{...x,[key]:value}:x));clear();};
 const changeSetting=(key:string,value:any)=>{setSettings(s=>({...s,[key]:value}));clear();};
 const start=async()=>{setError('');if(balancedFor!==selected){setError('Primeiro, balanceie a equação e aplique sua proporção à bancada.');if(mode!=='learn')setBalanceOpen(true);return;}if(inputs.some((_,i)=>!measured[i])){setError('Pese as amostras e meça as soluções antes de transferir.');return;}if(mode!=='explore'&&!prediction){setError('Registre uma previsão antes de misturar. Ela não precisa estar certa para você investigar.');return;}if([forecast.gas,forecast.residue].some(v=>v.trim()!==''&&(!Number.isFinite(num(v))||num(v)<0))){setError('Nas estimativas, use números maiores ou iguais a zero ou deixe o campo em branco.');return;}setLoading(true);try{const data=await api('/api/calculate',{reaction,inputs,settings});setSubmittedForecast({...forecast});setResult(data);setProgress(.001);setRunning(true);setGrade('');setManual('');const duration=window.matchMedia('(prefers-reduced-motion: reduce)').matches?500:6200,t0=performance.now();const step=(t:number)=>{const p=Math.min(1,(t-t0)/duration);setProgress(p);if(p<1)frame.current=requestAnimationFrame(step);else{setRunning(false);if(mode==='challenge'){const verdict=judgeChallenge(challengeId,data);setChallengeFeedback(verdict.passed?'Descoberta registrada! Explique o resultado e experimente outro caminho.':verdict.message);if(verdict.passed){setCompleted(old=>{const next={...old,[challengeId]:true};try{localStorage.setItem('bancada-discoveries',JSON.stringify(next));}catch{}return next;});}}setHistory(h=>[{id:Date.now(),reaction:reaction.id,name:reaction.name,result:data,inputs:structuredClone(inputs),settings:{...settings},forecast:{...forecast},prediction,coefficients:{reactants:reaction.reactants,products:reaction.products}},...h].slice(0,8));}};frame.current=requestAnimationFrame(step);}catch(e){setError((e as Error).message);}finally{setLoading(false);}};
 const generate=async()=>{setLoading(true);try{const data=await api('/api/generate',{reaction,inputs,settings,count:questionCount,target});setGenerated(data.questions);setSavedIds([]);setTab('questions');setToast('Questões geradas a partir das medidas da bancada.');}catch(e){setError((e as Error).message);setToast((e as Error).message);}finally{setLoading(false);}};
 const persist=async(kind:string,payload:any,id?:string)=>{try{const saved=await api('/api/catalog',{kind,payload,id});await loadCatalog();setToast('Cadastro salvo neste navegador. Exporte a biblioteca para compartilhar.');return saved.id;}catch(e){setToast((e as Error).message);return false;}};
 const remove=async(id:string)=>{try{await api('/api/catalog?id='+encodeURIComponent(id),undefined,'DELETE');await loadCatalog();setToast('Cadastro excluído.');if(selected===id)choose('zn-hcl');}catch(e){setToast((e as Error).message);}};
 const applyBalance=(r:any)=>{setReactions(old=>old.map(x=>x.id===selected?{...x,reactants:x.reactants.map((s,i)=>({...s,coef:r.reactants[i].coef})),products:x.products.map((s,i)=>({...s,coef:r.products[i].coef}))}:x));clear();setBalancedFor(selected);setBalanceOpen(false);setToast('Proporção balanceada aplicada ao experimento.');};
 const stage=progress===0?'Pronto para experimentar':progress<.32?'Transferindo os reagentes':progress<1?'Reação em andamento':'Experimento concluído';
 const newReaction=():Reaction=>({name:'',category:'Minha reação',description:'',reactants:[{formula:'',coef:1,phase:'s'},{formula:'',coef:1,phase:'aq'}],products:[{formula:'',coef:1,phase:'aq'}],note:'Reação única; impurezas inertes. Descreva aqui temperatura, meio, condições e simplificações.',reviewed:false});
 const newQuestion=():Question=>({reactionId:reaction.id!,reactionName:reaction.name,equation:unbalancedEquation(reaction),title:'',statement:'',answer:'',unit:'g',explanation:''});
 return <div className="app-shell">
 <header className="topbar"><a className="brand" href="./" aria-label="Bancada, início"><span className="brand-symbol"><FlaskConical size={23} strokeWidth={1.65}/></span><span>Bancada<span className="brand-dot">.</span><small>QUÍMICA PARA EXPLORAR</small></span></a>
 <nav aria-label="Navegação principal">{[{id:'lab',text:'Bancada',icon:FlaskConical},{id:'questions',text:'Questões',icon:BookOpen},{id:'teacher',text:'Área do professor',icon:GraduationCap}].map(n=><button key={n.id} disabled={running} className={tab===n.id?'nav-button active':'nav-button'} onClick={()=>{setTab(n.id);setError('');}}><n.icon size={17}/><span>{n.text}</span></button>)}</nav>
 <div className="header-actions"><button className="secondary new-trial" onClick={newTrial}><RotateCcw size={17}/>Recomeçar</button><button className="guide-button" onClick={()=>setHelp(true)}><HelpCircle size={17}/><span>Como funciona</span></button></div></header>
 <main>
 <div className="mode-selector" aria-label="Modo de aprendizagem">{[{id:'explore',title:'Explorar',text:'Experimente e compare'},{id:'learn',title:'Aprender',text:'Construa seu raciocínio'},{id:'challenge',title:'Desafios',text:'Investigue uma missão'}].map(m=><button key={m.id} disabled={running} className={mode===m.id?'selected':''} onClick={()=>{setMode(m.id);if(m.id==='challenge'){const c=CHALLENGES.find(x=>x.id===challengeId)!;choose(c.reactionId);}setError('');}}><strong>{m.title}</strong><small>{m.text}</small></button>)}</div>
 <div className="page-intro"><div className="title-with-art"><svg className="title-lab-art" viewBox="0 0 120 108" role="img" aria-label="Ilustração de vidrarias com líquido e bolhas"><circle cx="60" cy="54" r="49" fill="#e8efdc"/><g stroke="#315d48" strokeWidth="3" strokeLinejoin="round"><path d="M31 18h22m-18 0v26L17 77q-5 12 8 12h42q13 0 7-12L49 44V18" fill="#fcfdf9"/><path d="M28 61h30l14 19q3 6-5 6H25q-7 0-4-6Z" fill="#aacb85" stroke="none"/><path d="M75 35h29m-25 0v47q0 8 9 8h7q8 0 8-8V35" fill="#fcfdf9"/><path d="M82 61h18v20q0 6-6 6h-7q-5 0-5-6Z" fill="#dbad65" stroke="none"/><path d="M92 47h9m-9 9h9m-9 9h9" strokeWidth="2"/><circle cx="40" cy="69" r="3" fill="#fff" stroke="none"/><circle cx="50" cy="78" r="2" fill="#fff" stroke="none"/><circle cx="62" cy="26" r="4" fill="#d8e8b9"/><circle cx="70" cy="13" r="2" fill="#d8e8b9"/></g></svg><div><div className="eyebrow"><span/> LABORATÓRIO VIRTUAL · ESTEQUIOMETRIA</div><h1>{tab==='lab'?<>A química acontece <em>aqui.</em></>:tab==='questions'?<>Da experiência à <em>descoberta.</em></>:<>Seu conteúdo. Novas <em>possibilidades.</em></>}</h1><p>{tab==='lab'?'Pese, misture e observe. Cada medida conta uma parte da história.':tab==='questions'?'Investigue os resultados, teste seu raciocínio e conecte fenômenos a números.':'Cadastre reações, prepare atividades e transforme sua bancada em uma aula.'}</p></div></div><div className="intro-note"><span className="mini-orbit"><FlaskConical size={19}/></span><span>Observe o fenômeno.<br/><strong>Entenda a proporção.</strong></span></div></div>
 {catalogError&&<div className="notice"><AlertCircle size={16}/><span>Os exemplos estão disponíveis, mas seus cadastros não carregaram.</span><button onClick={loadCatalog}>Tentar novamente</button></div>}
 {tab==='lab'&&<>
 {mode==='challenge'&&<section className="challenge-panel card"><div className="challenge-cards">{CHALLENGES.map((c,i)=><button key={c.id} disabled={running} className={c.id===challengeId?'selected':''} onClick={()=>{setChallengeId(c.id);choose(c.reactionId);}}><span>{completed[c.id]?'✓':String(i+1).padStart(2,'0')}</span><strong>{c.title}</strong></button>)}</div><h2>{CHALLENGES.find(c=>c.id===challengeId)!.goal}</h2><p>{CHALLENGES.find(c=>c.id===challengeId)!.hint}</p>{challengeFeedback&&<div className="challenge-feedback" role="status">{challengeFeedback}</div>}<small>{Object.keys(completed).filter(k=>completed[k]).length} de 3 descobertas · sem cronômetro, sem ranking</small></section>}
 <div className="experiment-bar"><div className="experiment-label"><span className="number-badge">01</span><div><small>SEU EXPERIMENTO</small><label className="select-reaction"><select aria-label="Escolher reação" value={selected} disabled={running} onChange={e=>choose(e.target.value)}>{reactions.map(r=><option key={r.id} value={r.id}>{r.name}</option>)}</select><ChevronDown size={16}/></label></div></div></div>
 {mode!=='learn'&&<section className="card standalone-balance"><h2>Preparar a equação</h2><p>{balancedFor===selected?'✓ Proporção conferida. Você pode seguir para as medidas.':'Confira os coeficientes antes de preparar e misturar os reagentes.'}</p><button className="secondary" onClick={()=>setBalanceOpen(true)} disabled={running||loading}><Scale size={15}/>{balancedFor===selected?'Rever balanceamento':'Balancear equação'}</button></section>}
 {mode==='learn'&&<Learning key={selected} reaction={reaction} result={done?result:null} balanced={balancedFor===selected} allowAuto={allowAuto} onApply={applyBalance} onBalance={()=>setBalanceOpen(true)}/>}
 <div className="workspace">
 <aside className="card measures"><div className="card-heading"><h2><SlidersHorizontal size={17}/> Preparar reagentes</h2><span className="tiny-label">MEDIDAS</span></div>
 <fieldset disabled={running||loading}>
 {reaction.reactants.map((s,i)=><section className="reagent" key={i}><div className="reagent-title"><span className={'reagent-mark '+(i%2?'mint':'stone')}>{pretty(s.formula)}</span><div><h3>{s.name??pretty(s.formula)}</h3><small>{format(molarMass(s.formula),2)} g/mol · {s.phase==='s'?'sólido':s.phase==='aq'?'aquoso':s.phase==='g'?'gasoso':'líquido'}</small></div></div>
 <button className={'secondary measure-action '+(measured[i]?'registered':'')} onClick={()=>setInstrument(i)}>{s.phase==='s'?<Scale size={15}/>:<Beaker size={15}/>} {measured[i]?'✓ Medição registrada':s.phase==='s'?'Pesar na balança':'Medir na proveta'}</button>
 <label className="field"><span>Forma de medir</span><select value={inputs[i]?.mode} onChange={e=>update(i,'mode',e.target.value)}>{s.phase==='aq'?<><option value="commercial">Solução · % em massa</option><option value="molar">Solução · mol/L</option></>:<option value="mass">Massa da amostra</option>}</select></label>
 <div className="two-fields"><NumberField label={inputs[i]?.mode==='mass'?'Massa':'Volume'} value={inputs[i]?.quantity} onChange={v=>update(i,'quantity',v)} unit={inputs[i]?.mode==='mass'?'g':'mL'}/>
 {inputs[i]?.mode==='molar'?<NumberField label="Concentração" value={inputs[i]?.concentration} onChange={v=>update(i,'concentration',v)} unit="mol/L" max={20}/>:<NumberField label={inputs[i]?.mode==='mass'?'Pureza':'Teor (m/m)'} value={inputs[i]?.purity} onChange={v=>update(i,'purity',v)} unit="%" max={100}/>}</div>
 {inputs[i]?.mode!=='mass'?<NumberField label="Densidade da solução" value={inputs[i]?.density} onChange={v=>update(i,'density',v)} unit="g/mL" min={0.1} max={20}/>:inputs[i]?.purity<100&&<label className="field"><span>Impureza inerte</span><select value={inputs[i]?.impurity} onChange={e=>update(i,'impurity',e.target.value)}><option value="solid">Insolúvel · permanece no fundo</option><option value="dissolved">Solúvel · permanece dissolvida</option></select></label>}
 {s.formula==='HCl'&&inputs[i]?.mode==='commercial'&&<div className="reagent-hint"><Info size={12}/><span>PA é o grau analítico. O teor indica a massa de HCl na solução.</span></div>}
 </section>)}
 <details className="conditions"><summary><span><SlidersHorizontal size={15}/> Condições do ensaio</span><ChevronDown size={15}/></summary><div className="conditions-body"><div className="two-fields"><NumberField label="Temperatura" value={settings.temperature} onChange={v=>changeSetting('temperature',v)} unit="°C" min={-100} max={500}/><NumberField label="Pressão" value={settings.pressure} onChange={v=>changeSetting('pressure',v)} unit="kPa" min={1} max={10000}/></div><NumberField label="Conversão do limitante" value={settings.conversion} onChange={v=>changeSetting('conversion',v)} unit="%" max={100}/><small>Define quanto reage. Uma conversão menor deixa reagentes remanescentes.</small><NumberField label="Recuperação do produto" value={settings.recovery} onChange={v=>changeSetting('recovery',v)} unit="%" max={100}/><small>Define quanto é recolhido. As perdas não desfazem a reação.</small></div></details>
 </fieldset>
 </aside>
 <section className="card bench"><div className="bench-top"><h2><Beaker size={18}/> Bancada experimental</h2><span className={'status '+(running?'working':done?'finished':'')}><i/>{stage}</span></div>
 <div className="scene-wrap"><div className="scene-caption"><span>ENSAIO {String(history.length+(done?0:1)).padStart(2,'0')}</span><span>{format(settings.temperature)} °C <b>·</b> {format(settings.pressure,2)} kPa</span></div><LabScene reaction={reaction} result={result} progress={progress} running={running} system={settings.system}/><div className="scene-annotation"><span className="live-dot"/>{done?result?.gasVolume>0?'O gás se forma e o sólido remanescente fica visível.':result?.precipitate>0?'Um novo sólido se formou na mistura.':'Observe os produtos e o que permaneceu.':'Prepare as quantidades e inicie a transferência.'}</div></div>
 {result&&progress>0&&<div className="capacity-bars"><div className="capacity-label">DISPONIBILIDADE ESTEQUIOMÉTRICA <span>n / coeficiente · mol</span></div>{result.reactants.map((s:any)=>{const left=Math.max(0,s.capacity-result.extent*Math.max(0,Math.min(1,(progress-.32)/.68))),max=Math.max(...result.reactants.map((x:any)=>x.capacity),1e-12);return <div className="capacity-row" key={s.formula}><span>{pretty(s.formula)}</span><div><i style={{width:(left/max*100)+'%'}}/></div><b>{format(left,4)}</b></div>;})}</div>}<div className="bench-controls"><label className="system-toggle"><input type="checkbox" checked={settings.system==='collect'} disabled={running} onChange={e=>changeSetting('system',e.target.checked?'collect':'open')}/><span className="switch"/><span>Recolher o gás<small>{settings.system==='collect'?'Béquer + gás recolhido no sistema pesado':'Recipiente aberto · gás liberado no ambiente'}</small></span></label></div>
 <ForecastPanel value={forecast} onChange={setForecast} gas={reaction.products.some(s=>s.phase==='g')} disabled={running||done}/>
 <div className="prediction"><label htmlFor="prediction">Antes de misturar, o que você prevê?</label><select id="prediction" value={prediction} disabled={running||done} onChange={e=>setPrediction(e.target.value)}><option value="">Escolha sua previsão</option>{reaction.reactants.map(s=><option value={s.formula} key={s.formula}>{pretty(s.formula)} acaba primeiro</option>)}<option value="together">Proporção exata: acabam juntos</option></select></div>
 {error&&<div className="error-message" role="alert"><AlertCircle size={16}/>{error}</div>}
 <div className="action-row"><button className="primary start-button" disabled={running||loading} onClick={start}>{loading?<LoaderCircle className="spin" size={17}/>:running?<LoaderCircle className="spin" size={17}/>:done?<RotateCcw size={17}/>:<Play size={16} fill="currentColor"/>}{loading?'Conferindo medidas…':running?'Observe a transformação…':done?'Repetir experimento':'Transferir e misturar'}{!running&&!loading&&<ArrowRight size={17}/>}</button><p>Representação ilustrativa · duração sem escala cinética</p></div>
 <div className="experiment-progress">{['Preparar','Transferir','Observar'].map((s,i)=><span className={(i===0||i===1&&progress>.01||i===2&&progress>.32)?'complete':''} key={s}><b>{done?<Check size={10}/>:i+1}</b>{s}</span>)}</div>
 </section>
 <aside className="card notebook"><div className="card-heading"><h2><BookOpen size={17}/> Caderno de observações</h2><span className="tiny-label">AO VIVO</span></div>
 <div className="observation"><span className="observation-icon"><Layers size={20}/></span><span>CORPO DE FUNDO<strong>{done?format(result.residue)+' g':'—'}</strong><small>{done?result.residue>1e-8?'Sólidos presentes ao final':'Sem sólidos remanescentes':'O que permanece no béquer?'}</small></span></div>
 <div className="observation"><span className="observation-icon"><Wind size={20}/></span><span>GÁS FORMADO<strong>{done?format(result.gasVolume)+' L':'—'}</strong><small>{done?`Recolhido: ${format(result.collectedGas)} L`:'Bolhas contam uma história'}</small></span></div>
 <div className="observation"><span className="observation-icon"><Scale size={20}/></span><span>MASSA DO SISTEMA<strong>{done?format(result.massSystem,2)+' g':'—'}</strong><small>{done?`Inicial: ${format(result.massIn,2)} g · sem tara`:'Inclui a água das soluções'}</small></span></div>
 <div className="verdict"><div className="eyebrow"><span/>{done?'O QUE ACONTECEU':'OLHAR CIENTÍFICO'}</div>{done?<><h3>{result.extentMax===0?'Não há quantidade ativa para reagir.':result.reactants.every((s:any)=>s.lim)?'Proporção estequiométrica.':`${pretty(result.reactants.find((s:any)=>s.lim).formula)} é o limitante.`}</h3><p>{result.conversion<1?`A conversão de ${format(result.conversion*100)}% deixou parte dos reagentes sem reagir.`:result.residue>0?'Observe o que sobrou: excesso, impurezas ou produto sólido.':'Confira os produtos formados e as espécies que ficaram em solução.'}</p>{prediction&&<div className="prediction-feedback">{(prediction==='together'?result.reactants.every((s:any)=>s.lim):result.reactants.filter((s:any)=>s.lim).length===1&&result.reactants.some((s:any)=>s.lim&&s.formula===prediction))?'✓ Sua previsão confere com a proporção.':'Compare sua previsão com os valores de n/ν na ficha.'}</div>}</>:<><h3>Qual reagente vai acabar primeiro?</h3><p>Não é necessariamente o de menor massa. A resposta está na proporção entre os mols e os coeficientes.</p></>}</div>
 <button className="text-button notebook-link" onClick={()=>setShowMath(v=>!v)}>{showMath?'Recolher ficha de cálculo':'Explorar a ficha de cálculo'}<ArrowUpRight size={15}/></button>
 </aside>
 </div>
 <div className="under-bench"><span><Info size={14}/> Modelo de reação única · estados físicos definidos pelo professor</span><button className="text-button" onClick={()=>setShowMath(v=>!v)}><BookOpen size={14}/>{showMath?'Ocultar cálculos':'Mostrar cálculos'}<ChevronDown size={14}/></button></div>
 {showMath&&<section className="card calculation"><div className="section-heading"><div><div className="eyebrow">CADA NÚMERO TEM UMA ORIGEM</div><h2>Ficha de cálculo</h2></div><span className="category-tag">n → proporção → produto</span></div>{!done?<p className="muted">Conclua um experimento para acompanhar as contas das suas medidas.</p>:<>
 <div className="table-scroll"><table><thead><tr><th>Reagente</th><th>Origem da medida</th><th>Quantidade inicial</th><th>n / coeficiente</th><th>Remanescente</th></tr></thead><tbody>{result.reactants.map((s:any)=><tr key={s.formula}><td><strong>{pretty(s.formula)}</strong>{s.lim&&<span className="limit-tag">limitante</span>}</td><td className="formula-small">{s.input.mode==='commercial'?`${format(s.input.quantity)} × ${format(s.input.density)} × ${format(s.input.purity/100)} / ${format(s.M)}`:s.input.mode==='molar'?`${format(s.input.quantity/1000)} L × ${format(s.input.concentration)} mol/L`:`${format(s.input.quantity)} × ${format(s.input.purity/100)} / ${format(s.M)}`}</td><td>{format(s.n,5)} mol</td><td>{format(s.capacity,5)} mol</td><td>{format(s.leftMass,4)} g</td></tr>)}</tbody></table></div>
 <div className="formula-note">ξmáx = menor n/ν = {format(result.extentMax,6)} mol <ArrowRight size={14}/> ξ efetivo = ξmáx × {format(result.conversion*100)}% = {format(result.extent,6)} mol</div>
 <div className="table-scroll"><table><thead><tr><th>Produto</th><th>Estado</th><th>Teórico máximo</th><th>Formado</th><th>Recolhível após recuperação*</th></tr></thead><tbody>{result.products.map((s:any)=><tr key={s.formula}><td><strong>{pretty(s.formula)}</strong></td><td>{s.phase}</td><td>{format(s.theoreticalMass,4)} g</td><td>{format(s.mass,4)} g</td><td>{format(s.recovered,4)} g</td></tr>)}</tbody></table></div>
 <div className="calc-grid"><div><h3>O fundo do béquer</h3><p>Reagente sólido: {format(result.solidReagent)} g<br/>Precipitado: {format(result.precipitate)} g<br/>Impureza insolúvel: {format(result.impurity)} g</p></div><div><h3>O caminho do gás</h3><p>V = nRT/P · {format(result.vm,3)} L/mol<br/>Formado: {format(result.gasVolume)} L<br/>Liberado sem coleta: {format(result.uncollectedGas)} L</p></div><div><h3>Conservação da massa</h3><p>Solvente inicial: {format(result.solvent)} g<br/>Béquer ao final: {format(result.massBeaker)} g<br/>Sistema + gás liberado = {format(result.massIn)} g</p></div></div>
 <p className="footnote">* Projeção aplicando a mesma eficiência de recuperação a cada produto. Para gases, o recolhimento exige o coletor ativo; para sólidos e solutos, a separação não é animada. A balança mostra o sistema antes dessas separações.</p>
 <div className="yield-check"><div><h3>Quanto você conseguiu recolher?</h3><p>Escolha um produto e compare sua medida com a massa teórica máxima.</p></div><YieldCheck result={result}/></div>
 </>}
 <details className="model-details"><summary>Condições e limites deste modelo</summary><p>{reaction.note}</p><p>O nível dos líquidos e o tamanho dos sólidos são esquemáticos. Não há modelo de solubilidade, pH, equilíbrio, calor ou cinética. As condições de temperatura e pressão alimentam o cálculo do gás ideal.</p></details>
 </section>}
 <section className="learning-strip"><div className="learning-icon"><GraduationCap size={26}/></div><div><span className="eyebrow">UMA MEDIDA, MUITAS PERGUNTAS</span><h3>Leve seu experimento um passo além.</h3><p>Gere questões com as quantidades e condições que você escolheu.</p></div><button className="secondary" onClick={generate} disabled={running||loading}>Gerar questões<ArrowUpRight size={16}/></button></section>
 {done&&<ReactionEvidence result={result}/>}
 {done&&(submittedForecast.gas||submittedForecast.residue||submittedForecast.reason)&&<ForecastResult forecast={submittedForecast} result={result}/>}
 <Glossary/>
 {history.length>0&&<CompareTrials history={history}/>}
 {history.length>0&&<section className="history-section"><h2><History size={16}/> Ensaios desta sessão <span>{history.length}</span></h2><div className="history-grid">{history.map((h,i)=><button key={h.id} disabled={running} onClick={()=>{const r=reactions.find(r=>r.id===h.reaction);if(!r)return;setSelected(h.reaction);setInputs(h.inputs);setSettings(h.settings);setBalancedFor(h.reaction);setMeasured(h.inputs.map(()=>true));setResult(h.result);setProgress(1);setShowMath(true);setPrediction(h.prediction??'');setSubmittedForecast(h.forecast??emptyForecast());setForecast(h.forecast??emptyForecast());setManual('');setGrade('');}}><small>ENSAIO {String(history.length-i).padStart(2,'0')}</small><strong>{h.name}</strong><span>{format(h.result.residue)} g no fundo <b>·</b> {format(h.result.gasVolume)} L de gás</span><ArrowUpRight size={14}/></button>)}</div></section>}
 </>}
 {tab==='questions'&&<>
 <section className="card question-toolbar"><div><div className="eyebrow">ATIVIDADES PARAMETRIZADAS</div><h2>{reaction.name}</h2><p>As questões geradas usam as medidas atuais da bancada, variando a quantidade do primeiro reagente.</p></div><div className="row"><label className="field"><span>O que determinar</span><select value={target} onChange={e=>setTarget(e.target.value)}><option value="mixed">Explorações variadas</option>{Object.entries(TARGETS).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></label><label className="field"><span>Quantidade</span><select value={questionCount} onChange={e=>setQuestionCount(Number(e.target.value))}>{[3,6,9].map(n=><option key={n}>{n}</option>)}</select></label><button className="primary" onClick={generate} disabled={loading}>{loading?<LoaderCircle className="spin" size={16}/>:<Plus size={16}/>}Gerar questões</button></div></section>
 <div className="print-controls"><span>Lista para investigar e explicar</span><button className="secondary" disabled={!generated.length&&!questions.length} onClick={()=>{setPrintTeacher(false);requestAnimationFrame(()=>requestAnimationFrame(()=>window.print()));}}>Imprimir lista dos alunos</button><button className="secondary" disabled={!generated.length&&!questions.length} onClick={()=>{setPrintTeacher(true);requestAnimationFrame(()=>requestAnimationFrame(()=>window.print()));}}>Imprimir com gabarito</button></div>
 <div className="section-heading questions-heading"><h2>{generated.length?'Atividades selecionadas':'Sua biblioteca de questões'}</h2><span className="muted">Responda antes de consultar a resolução</span></div>
 {generated.length===0&&questions.length===0?<div className="empty-state"><BookOpen size={32}/><h3>A próxima descoberta começa com uma pergunta.</h3><p>Prepare uma mistura na bancada e gere suas primeiras questões, ou cadastre uma na área do professor.</p><button className="secondary" onClick={()=>setTab('lab')}>Ir para a bancada<ArrowRight size={16}/></button></div>:<div className="question-grid">{(generated.length?generated:questions).map((q,i)=><QuestionCard key={q.id??i} q={q} index={i} onSave={generated.length?async()=>{const id=await persist('question',q,q.id);if(id)setSavedIds(ids=>[...ids,q.id!]);}:undefined} saved={savedIds.includes(q.id!)}/>)}</div>}
 {generated.length>0&&questions.some(q=>!generated.some(g=>g.id===q.id))&&<><div className="section-heading questions-heading"><h2>Salvas na sua biblioteca</h2></div><div className="question-grid">{questions.filter(q=>!generated.some(g=>g.id===q.id)).map((q,i)=><QuestionCard key={q.id} q={q} index={i}/>)}</div></>}
 </>}
 {tab==='teacher'&&<>
 <div className="teacher-banner"><span className="teacher-symbol"><GraduationCap size={29}/></span><div><h2>Uma bancada com a sua assinatura.</h2><p>Cadastros salvos neste navegador. Exporte sua biblioteca para levar a outra máquina ou compartilhar.</p></div><span className="cloud-status"><Save size={16}/> Biblioteca local · sem conta</span></div>
 <TeacherTools reactions={reactions} onChanged={loadCatalog} onQuestions={q=>{setGenerated(q);setSavedIds(q.map(x=>x.id));setTab('questions');}} notify={setToast}/>
 <label className="checkbox-label automatic-policy"><input type="checkbox" checked={allowAuto} onChange={e=>{setAllowAuto(e.target.checked);try{localStorage.setItem('bancada-auto-help',String(e.target.checked));}catch{}}}/>Permitir ao aluno consultar o balanceamento automático como ajuda. Desligado por padrão.</label>
 <div className="teacher-toolbar"><div className="tabs"><button className={teacherTab==='reactions'?'selected':''} onClick={()=>setTeacherTab('reactions')}>Reações <span>{reactions.length}</span></button><button className={teacherTab==='questions'?'selected':''} onClick={()=>setTeacherTab('questions')}>Questões <span>{questions.length}</span></button></div><button className="primary" onClick={()=>teacherTab==='reactions'?setEditor(newReaction()):setQEditor(newQuestion())}><Plus size={17}/>{teacherTab==='reactions'?'Nova reação':'Nova questão'}</button></div>
 {teacherTab==='reactions'?<div className="reaction-grid">{reactions.map((r,i)=><article className="card reaction-card" key={r.id}><div className="reaction-card-top"><span className={'reaction-card-icon tint-'+i%3}>{r.products.some(s=>s.phase==='g')?<Wind size={23}/>:<Layers size={23}/>}</span><span className="category-tag">{seeds.some(s=>s.id===r.id)?'EXEMPLO':'MINHA REAÇÃO'}</span></div><h3>{r.name}</h3><p className="reaction-equation">{equation(r)}</p><p>{r.description||r.note}</p><div className="reaction-card-bottom"><button className="text-button" onClick={()=>{choose(r.id!);setTab('lab');}}>Abrir na bancada<ArrowUpRight size={14}/></button><div className="row"><button className="icon-button" aria-label={'Duplicar '+r.name} title="Duplicar" onClick={()=>setEditor({...structuredClone(r),id:undefined,name:r.name+' · cópia',reviewed:false})}><Copy size={16}/></button>{!seeds.some(s=>s.id===r.id)&&<><button className="icon-button" aria-label={'Editar '+r.name} onClick={()=>setEditor(structuredClone(r))}><Pencil size={16}/></button><button className="icon-button" aria-label={'Excluir '+r.name} onClick={()=>{if(window.confirm('Excluir esta reação da sua biblioteca?'))remove(r.id!);}}><Trash2 size={16}/></button></>}</div></div></article>)}</div>:<section className="card saved-question-list">{questions.length===0?<div className="empty-state"><BookOpen size={30}/><h3>Prepare sua primeira atividade.</h3><p>Cadastre uma questão própria ou gere perguntas a partir de uma reação.</p><button className="secondary" onClick={()=>setTab('questions')}>Gerar a partir da bancada<ArrowRight size={16}/></button></div>:questions.map((q,i)=><div className="saved-question-row" key={q.id}><span className="number-badge">{i+1}</span><div><h3>{q.title}</h3><p>{q.reactionName??'Questão personalizada'}</p></div><button className="icon-button" aria-label="Editar questão" onClick={()=>setQEditor(structuredClone(q))}><Pencil size={16}/></button><button className="icon-button" aria-label="Excluir questão" onClick={()=>{if(window.confirm('Excluir esta questão?'))remove(q.id!);}}><Trash2 size={16}/></button></div>)}</section>}
 <div className="author-note"><Info size={18}/><p><strong>O cálculo confere os átomos. Você define o contexto químico.</strong> Cadastre reações únicas com estados físicos e condições revisados. A geração de questões é determinística, com respostas calculadas; não inventa reações nem substitui sua revisão.</p></div>
 </>}
 </main>
 <footer><span className="footer-brand">Bancada.</span><span>Menos fórmulas soltas. Mais química acontecendo.</span><button onClick={()=>setHelp(true)}>Sobre o laboratório<ArrowUpRight size={13}/></button></footer>
 {toast&&<div className="toast" role="status"><Info size={17}/>{toast}<button className="icon-button" onClick={()=>setToast('')} aria-label="Fechar aviso"><X size={16}/></button></div>}
 {help&&<Modal title="Uma bancada para descobrir" onClose={()=>setHelp(false)}><div className="help-content">{[{n:'01',h:'Prepare uma experiência',p:'Escolha a reação e informe massas ou volumes. Para soluções comerciais, use o teor em massa e a densidade do rótulo.'},{n:'02',h:'Preveja, transfira e observe',p:'Escolha um possível limitante e inicie a mistura. A animação mostra a transferência, o gás e os sólidos. Os desenhos são esquemáticos.'},{n:'03',h:'Conecte medida e cálculo',p:'Abra a ficha para acompanhar mol, proporção, remanescentes e produtos. Conversão define quanto reage; recuperação define quanto é recolhido.'},{n:'04',h:'Crie sua própria aula',p:'Na área do professor, cadastre reações revisadas e questões. Salve as atividades e imprima uma lista com ou sem gabarito. A biblioteca é local e pode ser exportada. A bancada funciona sem conta e, após a primeira visita com conexão, pode ficar disponível offline.'}].map(s=><div key={s.n}><span className="number-badge">{s.n}</span><section><h3>{s.h}</h3><p>{s.p}</p></section></div>)}<p className="model-disclaimer">Simulação educacional, sem instruções para execução de experimentos reais. O modelo não inclui pH, equilíbrio químico, velocidade ou calor da reação.</p></div></Modal>}
 {editor&&<ReactionEditor initial={editor} onClose={()=>setEditor(null)} onSave={async(r)=>{const id=await persist('reaction',r,r.id);if(id)setEditor(null);}}/>}
 {balanceOpen&&<Modal title="Balancear a equação" wide onClose={()=>setBalanceOpen(false)}><BalancePanel initial={reaction} preserve={balancedFor===selected} allowAuto={allowAuto} onApply={applyBalance} onCreate={r=>{setEditor({...newReaction(),name:'Nova reação balanceada',reactants:r.reactants,products:r.products,reviewed:false});setBalanceOpen(false);}}/></Modal>}
 {qEditor&&<QuestionEditor initial={qEditor} reactions={reactions} onClose={()=>setQEditor(null)} onSave={async(q)=>{const id=await persist('question',q,q.id);if(id)setQEditor(null);}}/>}
 {instrument!==null&&<Modal title={reaction.reactants[instrument].phase==='s'?'Balança da bancada':'Proveta da bancada'} onClose={()=>setInstrument(null)}><Instrument species={reaction.reactants[instrument]} measure={inputs[instrument]} onConfirm={q=>{const i=instrument;update(i,'quantity',q);setMeasured(old=>inputs.map((_,j)=>j===i?true:!!old[j]));setInstrument(null);setToast('Medida registrada. Esse valor será usado no cálculo.');}}/></Modal>}
 <Worksheet questions={generated.length?generated:questions} teacher={printTeacher}/>
 </div>;
}

function YieldCheck({result}:{result:any}){const[p,setP]=useState(0),[amount,setAmount]=useState('');const s=result.products[p]??result.products[0],v=num(amount),y=s.theoreticalMass>0?v/s.theoreticalMass*100:NaN;return <div className="yield-form"><label className="field"><span>Produto</span><select value={p} onChange={e=>{setP(Number(e.target.value));setAmount('');}}>{result.products.map((x:any,i:number)=><option key={x.formula} value={i}>{pretty(x.formula)}</option>)}</select></label><label className="field"><span>Massa recolhida (g)</span><input type="text" inputMode="decimal" value={amount} onChange={e=>setAmount(e.target.value)} placeholder="Sua medida"/></label><output>{amount===''?'η = real / teórico × 100':v<0||!Number.isFinite(v)?'Informe uma massa válida.':!Number.isFinite(y)?'Não há produto teórico neste ensaio.':`${format(v)} / ${format(s.theoreticalMass)} × 100 = ${format(y,2)}%${y>100?' · confira umidade, pureza e medição.':''}`}</output></div>;}

function QuestionCard({q,index,onSave,saved}:{q:Question;index:number;onSave?:()=>void;saved?:boolean}){const[answer,setAnswer]=useState(''),[feedback,setFeedback]=useState(''),[solution,setSolution]=useState(false),[busy,setBusy]=useState(false);const check=()=>{if(!answer.trim()){setFeedback('Informe sua resposta primeiro.');return;}const ok=typeof q.answer==='number'?Number.isFinite(num(answer))&&Math.abs(num(answer)-q.answer)<=Math.max(1e-7,Math.abs(q.answer)*.01):answer.trim().toLocaleLowerCase('pt-BR')===String(q.answer).trim().toLocaleLowerCase('pt-BR');setFeedback(ok?'✓ Correto! Sua resposta confere.':'Revise as medidas e a proporção estequiométrica. Você pode consultar a resolução.');};return <article className="card question-card"><div className="question-meta"><span>QUESTÃO {String(index+1).padStart(2,'0')}</span><span>{(q.kind==='limiting'||q.kind==='limitante')?'REAGENTE LIMITANTE':q.unit==='%'?'RENDIMENTO':'RELAÇÕES QUANTITATIVAS'}</span></div><h3>{q.title}</h3><p className="question-equation">{q.equation}</p><p>{q.statement}</p><div className="answer-row"><label className="field"><span>Sua resposta {q.unit&&`(${q.unit})`}</span>{q.choices?<select value={answer} onChange={e=>{setAnswer(e.target.value);setFeedback('');}}><option value="">Selecione</option>{q.choices.map(c=><option key={c} value={c}>{pretty(c)}</option>)}</select>:<input aria-label="Sua resposta" value={answer} onChange={e=>{setAnswer(e.target.value);setFeedback('');}} inputMode={typeof q.answer==='number'?'decimal':'text'} placeholder={typeof q.answer==='number'?'Digite o valor':'Digite sua resposta'}/>}</label><button className="secondary" onClick={check}>Conferir<Check size={15}/></button></div>{feedback&&<p role="status" className={'answer-feedback '+(feedback.startsWith('✓')?'correct':'')}>{feedback}</p>}<div className="question-footer"><button className="text-button" onClick={()=>setSolution(!solution)}>{solution?'Ocultar resolução':'Ver resolução'}<ChevronDown size={14}/></button>{onSave&&<button className="text-button" disabled={saved||busy} onClick={async()=>{setBusy(true);try{await onSave();}finally{setBusy(false);}}}>{saved?<Check size={15}/>:<Save size={15}/>} {saved?'Salva':busy?'Salvando…':'Salvar questão'}</button>}</div>{solution&&<div className="solution"><strong>Resposta: {typeof q.answer==='number'?format(q.answer,5):pretty(q.answer)} {q.unit}</strong><p>{q.explanation}</p></div>}</article>;}

function ReactionEditor({initial,onClose,onSave}:{initial:Reaction;onClose:()=>void;onSave:(r:Reaction)=>Promise<void>}){const[r,setR]=useState<Reaction>(initial),[error,setError]=useState(''),[busy,setBusy]=useState(false);const field=(key:string,value:any)=>setR(x=>({...x,[key]:value}));const species=(side:'reactants'|'products',i:number,key:string,v:any)=>setR(x=>({...x,[side]:x[side].map((s,j)=>j===i?{...s,[key]:v}:s)}));return <Modal title={r.id?'Editar reação':'Nova reação'} wide onClose={onClose}><form onSubmit={async e=>{e.preventDefault();setError('');try{validateReaction(r);if(r.reactants.some(s=>s.phase==='g'))throw Error('Esta versão da bancada recebe sólidos, líquidos e soluções. Reagentes gasosos exigem outro aparato.');setBusy(true);await onSave({...r,defaults:r.reactants.map(defaultInput)});}catch(e){setError((e as Error).message);}finally{setBusy(false);}}} className="editor-form"><p className="muted">Defina a equação e o contexto. O sistema verifica a conservação dos átomos antes de salvar.</p><div className="two-fields"><label className="field"><span>Nome da experiência</span><input required minLength={3} maxLength={100} value={r.name} onChange={e=>field('name',e.target.value)} placeholder="Ex.: Magnésio + ácido clorídrico"/></label><label className="field"><span>Categoria</span><input required value={r.category} maxLength={50} onChange={e=>field('category',e.target.value)}/></label></div><label className="field"><span>Pergunta de abertura</span><input value={r.description??''} maxLength={200} onChange={e=>field('description',e.target.value)} placeholder="O que o aluno deve investigar?"/></label>
 {(['reactants','products'] as const).map(side=><section className="species-editor" key={side}><div className="section-heading"><h3>{side==='reactants'?'Reagentes':'Produtos'}</h3><button type="button" className="text-button" disabled={r[side].length>=(side==='reactants'?4:6)} onClick={()=>field(side,[...r[side],{formula:'',coef:1,phase:'aq'}])}><Plus size={14}/>Adicionar</button></div>{r[side].map((s,i)=><div className="species-row" key={i}><label className="field"><span>Fórmula</span><input required value={s.formula} onChange={e=>species(side,i,'formula',e.target.value.trim())} placeholder="Ca(OH)2"/></label><NumberField label="Coeficiente" value={s.coef} min={1} max={10000} step="1" onChange={v=>species(side,i,'coef',v)}/><label className="field"><span>Estado físico</span><select value={s.phase} onChange={e=>species(side,i,'phase',e.target.value)}><option value="s">s · sólido</option><option value="aq">aq · aquoso</option><option value="l">l · líquido</option>{side==='products'&&<option value="g">g · gás</option>}</select></label><button type="button" className="icon-button" aria-label="Remover espécie" disabled={r[side].length===1} onClick={()=>field(side,r[side].filter((_,j)=>j!==i))}><X size={17}/></button></div>)}</section>)}
 <div className="editor-balancer"><div><strong>Deixe o app encontrar os coeficientes.</strong><p>Preencha as fórmulas; o balanceador conserva cada elemento.</p></div><button type="button" className="secondary" disabled={busy} onClick={async()=>{setError('');setBusy(true);try{const data=await api('/api/balance',{reaction:r});setR(data.reaction);}catch(e){setError((e as Error).message);}finally{setBusy(false);}}}><Scale size={15}/>Balancear automaticamente</button></div><label className="field"><span>Condições e hipóteses do modelo</span><textarea required rows={3} maxLength={2000} value={r.note} onChange={e=>field('note',e.target.value)}/></label><label className="checkbox-label"><input type="checkbox" checked={r.reviewed} onChange={e=>field('reviewed',e.target.checked)}/>Revisei a reação, os estados físicos e as condições em que ela ocorre.</label><div className="notice small"><Info size={16}/><span>A bancada usa reação única, impurezas inertes e gases ideais. Precipitação e dissolução seguem os estados cadastrados, sem cálculo de equilíbrio.</span></div>{error&&<p className="error-message" role="alert">{error}</p>}<div className="modal-actions"><button type="button" className="secondary" onClick={onClose}>Cancelar</button><button className="primary" disabled={busy}>{busy?<LoaderCircle className="spin" size={16}/>:<Save size={16}/>}Salvar reação</button></div></form></Modal>;}

function QuestionEditor({initial,reactions,onClose,onSave}:{initial:Question;reactions:Reaction[];onClose:()=>void;onSave:(q:Question)=>Promise<void>}){const[q,setQ]=useState(initial),[numeric,setNumeric]=useState(typeof initial.answer==='number'),[busy,setBusy]=useState(false),[error,setError]=useState('');const field=(key:string,v:any)=>setQ(x=>({...x,[key]:v}));return <Modal title={q.id?'Editar questão':'Nova questão'} wide onClose={onClose}><form className="editor-form" onSubmit={async e=>{e.preventDefault();if(numeric&&!Number.isFinite(num(String(q.answer)))){setError('Informe um gabarito numérico válido.');return;}setBusy(true);try{await onSave({...q,choices:null,answer:numeric?num(String(q.answer)):String(q.answer).trim()});}finally{setBusy(false);}}}><label className="field"><span>Reação de referência</span><select value={q.reactionId} onChange={e=>{const r=reactions.find(x=>x.id===e.target.value)!;setQ(x=>({...x,reactionId:r.id!,reactionName:r.name,equation:unbalancedEquation(r)}));}}>{reactions.map(r=><option key={r.id} value={r.id}>{r.name}</option>)}</select></label><label className="field"><span>Pergunta</span><input required minLength={5} maxLength={1000} value={q.title} onChange={e=>field('title',e.target.value)} placeholder="Qual é a massa do precipitado?"/></label><label className="field"><span>Enunciado e dados</span><textarea required rows={4} maxLength={10000} value={q.statement} onChange={e=>field('statement',e.target.value)}/></label><div className="two-fields"><label className="field"><span>Tipo de resposta</span><select value={numeric?'number':'text'} onChange={e=>setNumeric(e.target.value==='number')}><option value="number">Numérica · tolerância de 1%</option><option value="text">Texto · correspondência exata</option></select></label><label className="field"><span>Unidade</span><input maxLength={30} value={q.unit} onChange={e=>field('unit',e.target.value)} placeholder="g, mol, L ou %"/></label></div><label className="field"><span>Gabarito</span><input required value={q.answer} inputMode={numeric?'decimal':'text'} onChange={e=>field('answer',e.target.value)}/></label><label className="field"><span>Resolução comentada</span><textarea required rows={3} maxLength={5000} value={q.explanation} onChange={e=>field('explanation',e.target.value)}/></label>{error&&<p className="error-message">{error}</p>}<div className="modal-actions"><button type="button" className="secondary" onClick={onClose}>Cancelar</button><button className="primary" disabled={busy}><Save size={16}/>{busy?'Salvando…':'Salvar questão'}</button></div></form></Modal>;}







